syntax:
auto function_name(parameters) -> deduced_return_type {
    // function body
}

or

auto function_name(parameters) {
    // function body
    return expression; // return type deduced from expression
}

code_example:
#include <iostream>
#include <vector>

template <typename T>
auto distance(const T& a, const T& b) -> decltype(b - a) {
    return b - a;
}

int main() {
    int a = 5, b = 10;
    auto dist = distance(a, b);
    std::cout << "Distance: " << dist << std::endl;
    return 0;
}
